function parseTipoEventoLabeled(text) {
  const m2 = text.match(/\bTipo\s+de\s+evento\s*:\s*([^\n.]{3,60})/i);
  if (!m2?.[1]) return null;
  const raw = m2[1].trim().replace(/\s+/g, " ");
  if (/^(cotizaci|servicio|catering|banquete)$/i.test(raw)) return null;
  return raw.slice(0, 80);
}
